"""scripts/audit_lock.py: pip-audit sees every pinned version, and nothing is let through without a reason."""

from __future__ import annotations

import importlib.util
import re
import subprocess
import sys
from pathlib import Path
from typing import List

import pytest

REPOSITORY = Path(__file__).resolve().parents[2]
SCRIPT = REPOSITORY / "scripts" / "audit_lock.py"
LOCK = REPOSITORY / "uv.lock"

EXPORT = """\
# This file was autogenerated by uv via the following command:
#    uv export --locked --all-extras --all-groups --no-emit-project --format requirements-txt
cffi==2.0.0 ; python_full_version < '3.10' and platform_python_implementation != 'PyPy' \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
cffi==2.1.1 ; python_full_version >= '3.10' and platform_python_implementation != 'PyPy' \\
    --hash=sha256:cccc
cryptography==50.0.2 \\
    --hash=sha256:dddd
jeepney==0.9.0 ; sys_platform == 'linux' \\
    --hash=sha256:eeee
Pytest_Cov==7.1.0 \\
    --hash=sha256:ffff
pytest==8.4.2 ; python_full_version < '3.10' \\
    --hash=sha256:1111
pytest==9.2.0 ; python_full_version >= '3.10' \\
    --hash=sha256:2222
pywin32-ctypes==0.2.3 ; sys_platform == 'win32' \\
    --hash=sha256:3333
"""


def load():
    spec = importlib.util.spec_from_file_location("audit_lock", SCRIPT)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class Runs:
    """Stands in for pip-audit: keeps what each run was given, and fails the runs it is told to."""

    def __init__(self, failing: int = 0) -> None:
        self.commands: List[List[str]] = []
        self.files: List[str] = []
        self.failing = failing

    def __call__(self, command: List[str], check: bool = False) -> "subprocess.CompletedProcess[bytes]":
        self.commands.append(command)
        self.files.append(Path(command[command.index("-r") + 1]).read_text(encoding="utf-8"))
        return subprocess.CompletedProcess(command, 1 if len(self.commands) == self.failing else 0)


def audit(tmp_path: Path, export: str = EXPORT, failing: int = 0):
    module = load()
    exported = tmp_path / "requirements.txt"
    exported.write_text(export, encoding="utf-8")
    runs = Runs(failing)
    return module, module.main([str(exported)], run=runs), runs


def test_every_pinned_version_reaches_pip_audit_whatever_its_marker_says(tmp_path: Path) -> None:
    """Found by a review: on Python 3.14 on a Mac, pip-audit left out what is pinned for 3.9, Linux and Windows."""
    _, status, runs = audit(tmp_path)
    assert status == 0
    given = "".join(runs.files)
    for pin in ("cffi==2.0.0", "cffi==2.1.1", "cryptography==50.0.2", "jeepney==0.9.0", "Pytest_Cov==7.1.0",
                "pytest==8.4.2", "pytest==9.2.0", "pywin32-ctypes==0.2.3"):  # fmt: skip
        assert len(re.findall(rf"^{re.escape(pin)} ", given, re.MULTILINE)) == 1, pin
    assert ";" not in given and "python_full_version" not in given and "sys_platform" not in given
    for digest in ("aaaa", "bbbb", "cccc", "dddd", "eeee", "ffff", "1111", "2222", "3333"):
        assert given.count(f"--hash=sha256:{digest}") == 1, "every hash goes with its pin"
    assert "--hash=sha256:aaaa \\\n    --hash=sha256:bbbb\n" in given


def test_a_package_pinned_twice_is_audited_in_two_runs_each_by_pip_audit_from_this_interpreter(tmp_path: Path) -> None:
    _, status, runs = audit(tmp_path)
    assert status == 0 and len(runs.commands) == 2
    assert "cffi==2.0.0" in runs.files[0] and "pytest==8.4.2" in runs.files[0]
    assert runs.files[1].count("==") == 2 and "cffi==2.1.1" in runs.files[1] and "pytest==9.2.0" in runs.files[1]
    for command in runs.commands:
        assert command[:3] == [sys.executable, "-m", "pip_audit"]
        assert "--disable-pip" in command and "--require-hashes" in command


def test_an_accepted_advisory_is_let_through_for_its_own_pin_only(tmp_path: Path) -> None:
    module, status, runs = audit(tmp_path)
    assert status == 0
    accepted = module.ACCEPTED[("pytest", "8.4.2")]
    assert accepted, "the test needs the entry it is about"
    first, second = runs.commands
    assert [first[i + 1] for i, word in enumerate(first) if word == "--ignore-vuln"] == list(accepted)
    assert "--ignore-vuln" not in second, "the newer pytest gets no exception"


def test_one_failing_run_fails_the_audit_and_the_other_runs_still_happen(tmp_path: Path) -> None:
    for failing in (1, 2):
        _, status, runs = audit(tmp_path, failing=failing)
        assert status == 1 and len(runs.commands) == 2


def test_an_accepted_pin_that_left_the_lock_fails_the_audit_before_anything_runs(
    tmp_path: Path, capsys: pytest.CaptureFixture[str]
) -> None:
    without = "".join(
        block for block in re.split(r"(?m)^(?=[A-Za-z])", EXPORT) if not block.startswith("pytest==8.4.2")
    )
    _, status, runs = audit(tmp_path, export=without)
    assert status == 1 and runs.commands == []
    assert "pytest==8.4.2 is no longer pinned: take it out of ACCEPTED" in capsys.readouterr().err


@pytest.mark.parametrize(
    "export",
    [
        "cryptography==50.0.2\n",  # no hash
        "cryptography==50.0.2 \\\n    --hash=sha256:dddd \\\n    --index-url https://elsewhere.example\n",
        "cryptography>=50.0.2 \\\n    --hash=sha256:dddd\n",  # not a pin
        "-e .\n",
        "",
    ],
)
def test_a_file_that_is_not_all_hashed_pins_is_refused(tmp_path: Path, export: str) -> None:
    _, status, runs = audit(tmp_path, export=export)
    assert status == 1 and runs.commands == []


def test_no_argument_is_a_usage_error() -> None:
    assert load().main([]) == 2


@pytest.mark.skipif(not LOCK.exists(), reason="uv.lock is not in the sdist")
def test_what_is_accepted_is_pinned_in_the_lockfile_and_each_entry_names_advisories() -> None:
    module = load()
    lock = LOCK.read_text(encoding="utf-8")
    pinned = set(re.findall(r'\[\[package\]\]\nname = "([^"]+)"\nversion = "([^"]+)"', lock))
    for pin, advisories in module.ACCEPTED.items():
        assert pin in pinned, pin
        assert advisories and all(re.fullmatch(r"(GHSA|PYSEC|CVE)-[\w-]+", name) for name in advisories), pin
    assert len(module.ACCEPTED) <= 1, "a second accepted advisory is a decision: write its reason, then raise this"
